mapper.select:
SELECT e.emp_id AS empId, e.emp_name AS empName, a.work_date AS workDate, a.check_in_time AS checkInTime, a.check_out_time AS checkOutTime, a.is_late AS isLate, a.is_early_leave AS isEarlyLeave, TIMESTAMPDIFF(MINUTE, a.check_in_time, a.check_out_time) / 60.0 AS workHours,
CASE WHEN a.check_in_time IS NULL AND l.leave_id IS NOT NULL THEN '휴가' WHEN a.check_in_time IS NULL AND b.business_id IS NOT NULL THEN '출장' WHEN a.check_in_time IS NULL THEN '결근' WHEN a.is_late = true THEN '지각' ELSE '출근' END AS status
FROM employee e LEFT JOIN attendance a ON e.emp_id = a.emp_id AND a.work_date BETWEEN #{startDate} AND #{endDate} LEFT JOIN leave l ON e.emp_id = l.emp_id AND l.leave_date = a.work_date LEFT JOIN business b ON e.emp_id = b.emp_id AND b.business_date = a.work_date WHERE e.emp_id = #{empId}
